function charFrequency(s) {
  const out = {};
  for (const c of s) {
    out[c] = (out[c] ?? 0) + 1;
  }
  return out;
}

function intersectUnique(a, b) {
  const setB = new Set(b);
  const seen = new Set();
  const out = [];
  for (const x of a) {
    if (setB.has(x) && !seen.has(x)) {
      seen.add(x);
      out.push(x);
    }
  }
  return out;
}

function sortNumbers(nums) {
  return nums.slice().sort((a, b) => a - b);
}
